/* SVS cost dashboard 0.1.32. View state is session-local; financial data comes from scoped backend. */
var CP028={data:null,loading:false,seq:0,view:'overview',compareBasis035:'month',group:'weaned',year:0,from:1,to:12,regions:[],bus:[],types:[],farm:'',search:'',exclude:[],sort:'desc',listOrder:'index',targetYear:0,table:'list',groupBy:'region',bars:false,chart:{},off:new Set(),composition:'value',colors:['red'],streak:'3',stage:null,busy:false,error:''};
const CP_REGIONS028=['ภาคเหนือ','ภาคกลาง','ภาคตะวันตก','ภาคใต้','ภาคอีสาน(บน)','ภาคอีสาน(ล่าง)','ภาคตะวันออก'];
const CP_MONTHS028=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const CP_COLORS028={red:'#b32235',orange:'#ed921e',yellow:'#d6b625',green:'#238252',unknown:'#a5afb2'};
const CP_LABELS028={red:'สูงทั้งสองดัชนี',orange:'ตาย-คัดทิ้งสูง',yellow:'ค่ายา-วัคซีนสูง',green:'ไม่เกินเป้าทั้งสอง',unknown:'ยังจัดกลุ่มไม่ได้'};
function cpReset028(){CP028.seq++;CP028.data=null;CP028.stage=null;CP028.loading=false;CP028.busy=false;CP028.view='overview';CP028.compareBasis035='month';CP028.off.clear();CP028.regions=[];CP028.bus=[];CP028.types=[];CP028.farm='';CP028.exclude=[];CP028.year=0;CP028.targetYear=0;CP028.error='';CP028.kpiEditYear=0;CP028.registrySearch='';CP028.registryMode='pending';CP028.bars=false;CP028.chart={};CP028.colors=['red'];CP028.streak='3';CP028.composition='value';}
function cpEsc028(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function cpN028(v,d=2){return v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('th-TH',{minimumFractionDigits:d,maximumFractionDigits:d});}
function cpFarm028(id){return CP028.data.farms.find(f=>f.id===id)||{id,name:'ไม่พบฟาร์ม',region:''};}
function cpTarget028(group=CP028.group){return CP028.data.kpis[CP028.targetYear||CP028.year]?.targets?.[group]||null;}
function cpReasons028(id){const h=CP028.data.health[id]||{};return CP028.exclude.filter(k=>k==='unstable'?h.prrs==='Unstable':k==='active'?h.prrs==='Stable Active':h.events?.includes(k));}
function cpBase028(group=CP028.group,year=CP028.year,exclude=true){return CP028.data.rows.filter(r=>r.group===group&&r.year===year&&r.month>=(cpIsCumulative035()?1:CP028.from)&&r.month<=CP028.to).filter(r=>{const f=cpFarm028(r.farmId);return (!CP028.regions.length||CP028.regions.includes(f.region))&&(!CP028.bus.length||CP028.bus.includes(r.bu))&&(!CP028.types.length||CP028.types.includes(farmType023(f)))&&(!exclude||!cpReasons028(f.id).length);});}
function cpRows028(group=CP028.group){const map=new Map();for(const r of cpBase028(group)){if(!map.has(r.farmId))map.set(r.farmId,[]);map.get(r.farmId).push(r);}const t=cpTarget028(group);return [...map].map(([id,rows])=>{const f=cpFarm028(id),values=Cost028.rates(rows);return {...f,rows,values,bu:[...new Set(rows.map(r=>r.bu))].sort().join(', '),index:Cost028.index(values,t),category:Cost028.category(values,t)};}).sort((a,b)=>Cost028.compare(a,b,CP028.sort));}
async function cpLoad028(){if(CP028.loading)return;CP028.loading=true;const seq=++CP028.seq,uid=state.user?.id;$('#app').innerHTML='<div class="panel">กำลังอ่านข้อมูลต้นทุน…</div>';try{const d=await api('costDashboard028');if(seq!==CP028.seq||uid!==state.user?.id)return;if(d.protocol!==30||!d.display?.revision)throw Error('กรุณาติดตั้งโมดูลต้นทุน v0.1.33-r1');CP028.data=d;if(!CP028.year){CP028.year=d.source?.year||new Date().getFullYear();CP028.to=d.source?.month||12;}CP028.error='';if(filter==='cost'&&!currentFarm&&!daActive021&&!adminData&&!currentRegion018)cpRender028();}catch(e){if(seq===CP028.seq&&filter==='cost'&&!currentFarm&&!daActive021&&!adminData&&!currentRegion018){$('#app').innerHTML='<div class="panel cp-error">'+cpEsc028(e.message)+'<p><button id="cpRetry">ลองใหม่</button></p></div>';$('#cpRetry').onclick=cpLoad028;}}finally{if(seq===CP028.seq)CP028.loading=false;}}
function cpOpen028(){daActive021=false;adminData=null;currentFarm=null;currentRegion018=null;filter='cost';render();}
function cpOptions028(values,selected){return values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${cpEsc028(v)}" ${String(v)===String(selected)?'selected':''}>${cpEsc028(l)}</option>`;}).join('');}
function cpMulti028(key,title,items){const values=CP028[key];return `<label>${title}<details class="cp-multi"><summary class="${values.length?'used':''}">${values.length?values.map(v=>items.find(i=>i[0]===v)?.[1]||v).join(', '):'ทั้งหมด'}</summary><div>${items.map(([v,l])=>`<label><input type="checkbox" data-cp-multi="${key}" value="${cpEsc028(v)}" ${values.includes(v)?'checked':''}>${cpEsc028(l)}</label>`).join('')}<button data-cp-apply="${key}">ใช้ตัวกรอง</button><button data-cp-clear="${key}">ล้าง</button></div></details></label>`;}
function cpPanel028(key,title,body,tools='',long=false){return `<section class="panel ${long?'cp-long':''}" data-cp-panel="${key}"><div class="cp-head"><h2>${title}</h2><label class="cp-noexport"><input type="checkbox" data-cp-export="${key}" ${!CP028.off.has(key)?'checked':''}>ส่งออกส่วนนี้</label></div>${tools?`<div class="cp-tools cp-panel-tools cp-screen">${tools}</div>`:''}${body}</section>`;}
function cpControls028(){const years=[...new Set(CP028.data.rows.map(r=>r.year))].sort((a,b)=>b-a);if(!years.includes(CP028.year))years.unshift(CP028.year);const regions=['ภาคเหนือ','ภาคกลาง','ภาคตะวันตก','ภาคใต้','ภาคอีสาน(บน)','ภาคอีสาน(ล่าง)','ภาคตะวันออก'];return `<div class="panel cp-tools cp-screen"><label>ปี<select data-cp="year">${cpOptions028(years.map(y=>[y,y+543]),CP028.year)}</select></label><label>ชุดเป้าหมาย<select data-cp="targetYear">${cpOptions028([[0,'ตามปีที่เลือก'],...Object.keys(CP028.data.kpis).map(y=>[y,'KPI ปี '+(+y+543)])],CP028.targetYear)}</select></label><label>ตั้งแต่เดือน<select data-cp="from">${cpOptions028(CP_MONTHS028.map((m,i)=>[i+1,m]),CP028.from)}</select></label><label>ถึงเดือน<select data-cp="to">${cpOptions028(CP_MONTHS028.map((m,i)=>[i+1,m]),CP028.to)}</select></label>${cpMulti028('regions','ภาค',regions.map(x=>[x,x]))}${cpMulti028('bus','ธุรกิจ',[...new Set(CP028.data.rows.map(r=>r.bu))].sort().map(x=>[x,x]))}${cpMulti028('types','ประเภทฟาร์ม',FARM_TYPES023.map(x=>[x[0],x[1]]))}<button id="cpResetFilters">ล้างตัวกรอง</button></div><div class="cp-tabs cp-screen">${Object.entries(Cost028.groups).map(([k,g])=>`<button data-cp-group="${k}" class="${CP028.group===k?'primary':''}">${g.label}</button>`).join('')}</div>`;}
function cpExclusions028(){const all=new Set(cpBase028(CP028.group,CP028.year,false).map(r=>r.farmId)),cut=[...all].filter(id=>cpReasons028(id).length);return `<div class="panel cp-screen"><div class="cp-head"><h2>คัดกรองด้วยสถานะปัจจุบัน</h2><span class="cp-muted">ข้อมูล ณ ${cpEsc028(new Date(CP028.data.loadedAt).toLocaleString('th-TH'))}</span></div><div class="cp-tabs">${[['unstable','ตัด PRRS: Unstable'],['active','ตัด PRRS: Stable Active'],['PRRS','ตัดเคส PRRS ที่เปิดอยู่'],['D1','ตัดเคส D1 ที่เปิดอยู่']].map(([v,l])=>`<label><input type="checkbox" data-cp-exclude="${v}" ${CP028.exclude.includes(v)?'checked':''}> ${l}</label>`).join('')}</div><div>ทั้งหมด ${all.size} ฟาร์ม · ใช้คำนวณ ${all.size-cut.length} ฟาร์ม · ตัดออก ${cut.length} ฟาร์ม</div>${cut.length?`<details><summary>ดูรายชื่อและเหตุผล</summary>${cut.map(id=>`<p>${cpEsc028(cpFarm028(id).name)} — ${cpEsc028(cpReasons028(id).join(', '))}</p>`).join('')}</details>`:''}</div>`;}
function cpMeta028(){const d=CP028;return `<p class="cp-muted">${Cost028.groups[d.group].label} · ปี ${d.year+543} · ${CP_MONTHS028[d.from-1]}–${CP_MONTHS028[d.to-1]} · ${cpEsc028(d.regions.join(', ')||'ทุกภาค')} · ${cpEsc028(d.bus.join(', ')||'ทุกธุรกิจ')} · ${cpEsc028(d.types.map(k=>FARM_TYPES023.find(t=>t[0]===k)?.[1]||k).join(', ')||'ทุกประเภทฟาร์ม')}<br>คัดกรองสถานะปัจจุบัน: ${cpEsc028(d.exclude.join(', ')||'ไม่ตัดฟาร์ม')} · ชุดต้นทุน ${cpEsc028(d.data.source?.name||'ยังไม่มีข้อมูล')} · ${d.data.display?.pendingCount!=null?'รอตรวจ '+d.data.display.pendingCount+' รหัส (ไม่รวมในยอด)':'ไม่รวมรหัสรอตรวจ'} · พักการแสดง ${d.data.display?.excluded?.length||0} รหัสต้นทุน · เป้าหมาย ${cpEsc028(d.data.kpis[d.targetYear||d.year]?.name||'ยังไม่มีเป้าหมายปีนี้')}</p>`;}
function cpStat028(label,v,t,unit){const diff=v!==null&&t>0?v-t:null;return `<div class="cp-stat"><span>${label}<small class="cp-unit"> (${unit})</small></span><b class="${diff===null?'':diff<=0?'cp-good':'cp-bad'}">${cpN028(v)}</b><small>เป้า ${cpN028(t)}${diff!==null?` · ${diff===0?'เท่ากับเป้า':(diff<0?'ต่ำกว่าเป้า ':'สูงกว่าเป้า ')+cpN028(Math.abs(diff))+' ('+cpN028(Math.abs(diff/t*100),1)+'%)'}`:''}</small></div>`;}
function cpSvg028(w,h,inside){return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img">${inside}</svg>`;}
function cpText028(x,y,text,size=12,fill='#42595e',anchor='middle',extra=''){return `<text x="${x}" y="${y}" fill="${fill}" font-size="${size}" text-anchor="${anchor}" ${extra}>${cpEsc028(text)}</text>`;}
function cpChartState028(key){return CP028.chart[key]||(CP028.chart[key]={mode:'cum',kind:'bar',prev:false});}
function cpChartTools028(key){const c=cpChartState028(key);return `<select data-cp-chart="${key}" data-prop="mode" aria-label="ช่วงคำนวณ">${cpOptions028([['month','รายเดือน'],['cum','สะสม']],c.mode)}</select><select data-cp-chart="${key}" data-prop="kind" aria-label="ชนิดกราฟ">${cpOptions028([['bar','กราฟแท่ง'],['line','กราฟเส้น']],c.kind)}</select><label class="cp-noexport"><input type="checkbox" data-cp-chart="${key}" data-prop="prev" ${c.prev?'checked':''}>ปีก่อนหน้า</label>`;}
function cpTrend028(group,metric,key,farmId){const cfg=cpChartState028(key),w=720,h=280,L=55,T=24,W=640,H=190,monthList=Array.from({length:CP028.to-CP028.from+1},(_,i)=>i+CP028.from);const series=[CP028.year,...(cfg.prev?[CP028.year-1]:[])].map(year=>{let rows=cpBase028(group,year);if(cfg.mode==='cum'){const old=CP028.from;CP028.from=1;try{rows=cpBase028(group,year);}finally{CP028.from=old;}}if(farmId)rows=rows.filter(r=>r.farmId===farmId);return monthList.map(m=>{if(!rows.some(r=>r.month===m))return null;return Cost028.rates(rows.filter(r=>cfg.mode==='cum'?r.month<=m:r.month===m))[metric];});});const target=cpTarget028(group)?.[metric],max=Math.max(1,target||0,...series.flat().filter(v=>v!==null))*1.18,min=Math.min(0,...series.flat().filter(v=>v!==null)),yy=v=>T+H-(v-min)/(max-min)*H,step=W/monthList.length;let s=`<path d="M${L},${T}V${T+H}H${L+W}" fill="none" stroke="#bccccc"/>`;for(let i=0;i<=4;i++){let v=min+(max-min)*i/4;s+=cpText028(L-7,yy(v)+4,cpN028(v,max<5?2:0),10,'#687e83','end');}if(target>0)s+=`<path d="M${L},${yy(target)}H${L+W}" stroke="#c49626" stroke-dasharray="6 5"/>`+cpText028(L+W,yy(target)-5,'เป้า '+cpN028(target),10,'#9c741c','end');const colors=[group==='gdu'?'#8b65b3':group==='fatten'?'#da872b':'#238580','#a7b2b6'];series.forEach((vs,k)=>{let previous=null;vs.forEach((v,i)=>{if(v===null){previous=null;return;}let x=L+step*(i+.5),y=yy(v);if(cfg.kind==='bar'){const bw=Math.min(22,step/(series.length+1));x+=((k?-.5:.5)*(series.length===1?0:bw));s+=`<rect x="${x-bw/2}" y="${Math.min(yy(0),y)}" width="${bw-2}" height="${Math.abs(yy(0)-y)}" rx="2" fill="${colors[k]}"/>`;}else{if(previous)s+=`<path d="M${previous.x},${previous.y}L${x},${y}" fill="none" stroke="${colors[k]}" stroke-width="2.5"/>`;s+=`<circle cx="${x}" cy="${y}" r="3" fill="${colors[k]}"/>`;previous={x,y};}if(!k)s+=cpText028(x,y-6,cpN028(v,group==='weaned'?1:2),10,colors[k]);});});monthList.forEach((m,i)=>s+=cpText028(L+step*(i+.5),T+H+20,CP_MONTHS028[m-1],11));s+=cpText028(w/2,h-10,`${cfg.mode==='cum'?'สะสม ม.ค. ถึงแต่ละเดือน':'รายเดือน'} · ${CP028.year+543}${cfg.prev?' / '+(CP028.year+542)+' (สีเทา)':''} · ${Cost028.groups[group].unit}`,11);return cpSvg028(w,h,s);}
function cpOverview028(){const gs=CP028.group==='gdu'?['gdu']:['weaned','fatten'];return `<div class="cp-grid">${gs.map(g=>{const v=Cost028.rates(cpBase028(g)),t=cpTarget028(g);return cpPanel028('summary-'+g,Cost028.groups[g].label,`<div class="cp-stats">${cpStat028('ค่ายา-วัคซีน',v.medvac,t?.medvac,Cost028.groups[g].unit)}${cpStat028('ตาย-คัดทิ้ง',v.deadcull,t?.deadcull,Cost028.groups[g].unit)}</div>`);}).join('')}</div><div class="cp-grid">${gs.flatMap(g=>['medvac','deadcull'].map(metric=>{const key=g+'-'+metric;return cpPanel028(key,cpTrendTitle031(Cost028.groups[g].label+' · '+(metric==='medvac'?'ค่ายา-วัคซีน':'ตาย-คัดทิ้ง'),g,metric,key),cpTrend028(g,metric,key),cpChartTools028(key));})).join('')}</div>`+cpRegionOverview028(gs);}
function cpQuadrant028(list){const t=cpTarget028();if(!t)return '<p>ยังไม่มีเป้าหมายปีนี้ จึงยังจัดกลุ่มไม่ได้</p>';const valid=list.filter(x=>x.category!=='unknown'),w=700,h=380,L=65,T=30,W=605,H=280,maxX=Math.max(t.medvac*1.8,...valid.map(x=>x.values.medvac))*1.08,maxY=Math.max(t.deadcull*1.8,...valid.map(x=>x.values.deadcull))*1.08,xx=v=>L+v/maxX*W,yy=v=>T+H-v/maxY*H,X=xx(t.medvac),Y=yy(t.deadcull);const qs=[['orange',L,T,X-L,Y-T],['red',X,T,L+W-X,Y-T],['green',L,Y,X-L,T+H-Y],['yellow',X,Y,L+W-X,T+H-Y]];let s=qs.map(([k,x,y,ww,hh])=>`<rect x="${x}" y="${y}" width="${ww}" height="${hh}" fill="${CP_COLORS028[k]}" opacity=".07"/>`+cpText028(x+ww/2,y+hh/2+17,valid.filter(f=>f.category===k).length,52,CP_COLORS028[k],'middle','opacity=".20" font-weight="bold"')).join('');s+=`<path d="M${X},${T}V${T+H}M${L},${Y}H${L+W}" fill="none" stroke="#ba9326" stroke-dasharray="5 5"/>`;s+=cpText028(X,T-10,cpN028(t.medvac),11,'#a87e16')+cpText028(L-7,Y+4,cpN028(t.deadcull),11,'#a87e16','end');valid.forEach(f=>s+=`<circle cx="${xx(f.values.medvac)}" cy="${yy(f.values.deadcull)}" r="5" fill="${CP_COLORS028[f.category]}" stroke="#fff" data-cp-farm="${cpEsc028(f.id)}" tabindex="0"><title>${cpEsc028(f.name)} · ยา ${cpN028(f.values.medvac)} · ตาย ${cpN028(f.values.deadcull)}</title></circle>`);s+=cpText028(w/2,h-16,'ค่ายา-วัคซีน ('+Cost028.groups[CP028.group].unit+')',12)+`<text transform="translate(18,180) rotate(-90)" text-anchor="middle" fill="#42595e" font-size="12">ตาย-คัดทิ้ง (${Cost028.groups[CP028.group].unit})</text>`;s+=cpText028(L,T+H+20,'0',10)+cpText028(L+W,T+H+20,cpN028(maxX),10);return cpSvg028(w,h,s)+cpLegend028();}
function cpLegend028(){return `<div class="cp-legend">${Object.entries(CP_LABELS028).map(([k,l])=>`<span><i style="background:${CP_COLORS028[k]}"></i>${l}</span>`).join('')}</div>`;}
function cpRanking028(list,metric='medvac'){const w=570,h=Math.max(70,40+list.length*24),L=205,W=280,values=list.map(r=>r.values[metric]).filter(v=>v!==null&&Number.isFinite(v)),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1,x=v=>L+(v-min)/span*W,t=cpTarget028()?.[metric];let s='';list.forEach((f,i)=>{const y=24+i*24,v=f.values[metric];s+=cpText028(L-10,y+4,f.name.length>28?f.name.slice(0,27)+'…':f.name,12,'#42595e','end');if(v!==null){s+=`<rect x="${Math.min(x(0),x(v))}" y="${y-10}" width="${Math.abs(x(v)-x(0))}" height="15" fill="${cpTone031(v,t)==='cp-good'?'#177846':cpTone031(v,t)==='cp-bad'?'#a81e30':'#89999c'}" rx="2"><title>${cpEsc028(f.name)}: ${cpN028(v)} ${Cost028.groups[CP028.group].unit}</title></rect>`;}s+=cpText028(L+W+8,y+4,cpN028(v),11,'#42595e','start');});return cpSvg028(w,h,s);}
function cpListTable028(list){const ordered=CP028.listOrder==='index'?list:list.slice().sort((a,b)=>{const order=['red','orange','yellow','green','unknown'];return order.indexOf(a.category)-order.indexOf(b.category)||(b.values.deadcull??-Infinity)-(a.values.deadcull??-Infinity)||Cost028.compare(a,b,CP028.sort);});return `<div class="cp-tablewrap"><table><thead><tr><th>ฟาร์ม</th><th>ภาค</th><th>ตาย-คัดทิ้ง</th><th>ค่ายา-วัคซีน</th><th>กลุ่ม</th></tr></thead><tbody>${ordered.map(f=>`<tr><td><button data-cp-farm="${cpEsc028(f.id)}">${cpEsc028(f.name)}</button></td><td>${cpEsc028(f.region)}</td><td class="num">${cpN028(f.values.deadcull)}</td><td class="num">${cpN028(f.values.medvac)}</td><td class="cp-${f.category}">${CP_LABELS028[f.category]}</td></tr>`).join('')}</tbody></table></div>`;}
function cpGroupTable028(list){const k=CP028.groupBy,labels=[...new Set(list.map(f=>f[k]))].sort((a,b)=>k==='region'?CP_REGIONS028.indexOf(a)-CP_REGIONS028.indexOf(b):a.localeCompare(b,'th'));return `<div class="cp-tablewrap"><table><thead><tr><th>${k==='region'?'ภาค':'ธุรกิจ'}</th>${['red','orange','yellow','green'].map(c=>`<th class="cp-${c}">${CP_LABELS028[c]}</th>`).join('')}</tr></thead><tbody>${labels.map(l=>`<tr><th>${cpEsc028(l)}</th>${['red','orange','yellow','green'].map(c=>`<td>${list.filter(f=>f[k]===l&&f.category===c).map(f=>`<div class="cp-farm cp-${c}" data-cp-farm="${cpEsc028(f.id)}" tabindex="0"><b>${cpEsc028(f.name)}</b><small>ตาย-คัดทิ้ง ${cpN028(f.values.deadcull)}<br>ค่ายา-วัคซีน ${cpN028(f.values.medvac)}</small></div>`).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${list.some(f=>f.category==='unknown')?'<p class="cp-muted">ยังจัดกลุ่มไม่ได้: '+list.filter(f=>f.category==='unknown').map(f=>cpEsc028(f.name)).join(', ')+'</p>':''}`;}
function cpHeat028(list){const end=cpLatest031(),chosen=CP028.streak,shown=list.filter(f=>chosen==='all'||cpRedRun031(f.id,Number(chosen),end));return `<p class="cp-muted cp-heat-context">ปี ${CP028.year+543} · ${cpEsc028(CP028.regions.join(', ')||'ทุกภาค')} · ${chosen==='all'?'ทุกฟาร์ม':'แดง '+chosen+' เดือน'}${end?' · ถึง '+CP_MONTHS028[end.month-1]+' '+(end.year+543):' · ยังไม่มีข้อมูล'}</p><div class="cp-tablewrap"><table class="cp-heat"><thead><tr><th>ฟาร์ม / ปี ${CP028.year+543}</th>${CP_MONTHS028.map(m=>'<th>'+m+'</th>').join('')}</tr></thead><tbody>${shown.map(f=>`<tr><th class="${cpRedRun031(f.id,3,end)?'cp-bad cp-bold031':''}">${cpEsc028(f.name)}</th>${Array.from({length:12},(_,i)=>{const rows=cpMonthRows031(f.id,CP028.year,i+1);if(!rows.length)return '<td></td>';const v=Cost028.rates(rows),c=Cost028.category(v,cpTarget028());return `<td><span class="cp-cell cp-${c}" title="${cpEsc028(f.name)} · ${CP_MONTHS028[i]} · ${CP_LABELS028[c]} · ตาย-คัดทิ้ง ${cpN028(v.deadcull)} · ค่ายา-วัคซีน ${cpN028(v.medvac)}" aria-label="${CP_LABELS028[c]}"></span></td>`;}).join('')}</tr>`).join('')}${!shown.length?'<tr><td colspan="13" class="cp-muted">ไม่พบฟาร์มตามเงื่อนไขที่เลือก</td></tr>':''}</tbody></table></div>${cpLegend028()}`;}
function cpCompare028(){const list=cpRows028(),selected=CP028.colors.length?CP028.colors:['red','orange','yellow','green'],filtered=list.filter(f=>selected.includes(f.category));const tools=`<label class="cp-noexport"><input type="checkbox" id="cpBars" ${CP028.bars?'checked':''}>แสดงกราฟแท่งแนวนอน</label><label>เรียงตารางตาม Index<select data-cp="sort">${cpOptions028([['desc','สูง → ต่ำ (แย่ที่สุดก่อน)'],['asc','ต่ำ → สูง']],CP028.sort)}</select></label>`;return `<div class="cp-tools cp-screen">${tools}</div>${CP028.bars?cpPanel028('rank','ต้นทุนรายฟาร์ม · '+Cost028.groups[CP028.group].unit,cpRankPair031(list),'',true):''}${cpPanel028('quadrant','ค่ายา-วัคซีน × ตาย-คัดทิ้ง',cpQuadrant028(list))}${cpPanel028('farms','กลุ่มฟาร์มตามสี · '+Cost028.groups[CP028.group].unit,`<p class="cp-muted">กลุ่มสี: ${selected.map(c=>CP_COLOR_NAMES031[c]).join(', ')} · ${filtered.length} ฟาร์ม</p>`+(CP028.table==='list'?cpListTable028(filtered):cpGroupTable028(filtered)),`${cpMulti028('colors','กลุ่มสี',Object.entries(CP_COLOR_NAMES031))}<select data-cp="listOrder" aria-label="วิธีเรียงรายการ">${cpOptions028([['index','เรียงตาม Index'],['color','เรียงสี / ตาย-คัดทิ้งสูงก่อน']],CP028.listOrder)}</select><select data-cp="table">${cpOptions028([['list','ตารางรายชื่อฟาร์ม'],['groups','แยกกลุ่มสี']],CP028.table)}</select>${CP028.table==='groups'?`<select data-cp="groupBy">${cpOptions028([['region','แยกตามภาค'],['bu','แยกตามธุรกิจ']],CP028.groupBy)}</select>`:''}`,true)}${cpPanel028('heat','สถานะต้นทุนรายเดือน',cpHeat028(cpAllYearFarms028()),cpHeatTools031(),true)}`;}
function cpAllYearFarms028(){const from=CP028.from,to=CP028.to;let list;CP028.from=1;CP028.to=12;try{list=cpRows028();}finally{CP028.from=from;CP028.to=to;}const index=new Map(cpRows028().map(f=>[f.id,f.index]));return list.map(f=>({...f,index:index.get(f.id)??null})).sort((a,b)=>Cost028.compare(a,b,CP028.sort));}
function cpComposition028(rows){const group=CP028.group,ms=Array.from({length:CP028.to-CP028.from+1},(_,i)=>CP028.from+i),vals=ms.map(m=>Cost028.rates(rows.filter(r=>r.month===m))),pct=CP028.composition==='percent',max=Math.max(1,...vals.map(v=>v.medvac||0))*1.2,W=650,H=190,L=55,T=25,step=W/ms.length;let s=`<path d="M${L},${T}V${T+H}H${L+W}" fill="none" stroke="#bccccc"/>`;for(let j=0;j<=4;j++)s+=cpText028(L-7,T+H-H*j/4+4,cpN028(max*j/4,group==='weaned'?0:2),10,'#687e83','end');vals.forEach((v,i)=>{if(v.medvac===null||v.med===null||v.vac===null||v.medvac<0||v.other<-.001)return;let bottom=T+H;const x=L+step*(i+.5),bw=Math.min(38,step*.65);[['vac','#9778ba'],['med','#27847e'],['other','#aebabe']].forEach(([k,col])=>{const value=Math.max(0,v[k]),label=pct?(v.medvac>0?value/v.medvac*100:0):value,hh=value/max*H;s+=`<rect x="${x-bw/2}" y="${bottom-hh}" width="${bw}" height="${hh}" fill="${col}"><title>${{vac:'วัคซีน',med:'ยา',other:'ส่วนต่าง'}[k]} ${cpN028(value)} ${Cost028.groups[group].unit}</title></rect>`;if(hh>15)s+=cpText028(x,bottom-hh/2+4,cpN028(label,pct?0:group==='weaned'?1:2)+(pct?'%':''),10,'#fff');bottom-=hh;});s+=cpText028(x,bottom-7,cpN028(v.medvac,group==='weaned'?1:2),10,'#20383d');});ms.forEach((m,i)=>s+=cpText028(L+step*(i+.5),T+H+20,CP_MONTHS028[m-1],11));return cpSvg028(750,265,s)+`<div class="cp-legend"><span><i style="background:#9778ba"></i>วัคซีน</span><span><i style="background:#27847e"></i>ยา</span><span><i style="background:#aebabe"></i>ส่วนต่างในยอดรวม</span></div><p class="cp-muted">ความสูงแท่ง: ต้นทุนจริง (${Cost028.groups[group].unit}) · ตัวเลขในแท่ง: ${pct?'สัดส่วน (%)':'ต้นทุนต่อหน่วย'}</p>`;}
function cpFarmView028(){const list=cpRows028().filter(f=>!CP028.search||f.name.toLowerCase().includes(CP028.search.toLowerCase()));if(!list.some(f=>f.id===CP028.farm))CP028.farm=list[0]?.id||'';const f=list.find(f=>f.id===CP028.farm);const controls=`<div class="panel cp-tools cp-screen"><label>ค้นหาฟาร์ม<input id="cpFarmSearch" value="${cpEsc028(CP028.search)}" placeholder="พิมพ์ชื่อฟาร์ม"></label><label>ฟาร์ม<select data-cp="farm">${cpOptions028(list.map(f=>[f.id,f.name]),CP028.farm)}</select></label></div>`;if(!f)return controls+'<div class="panel">ไม่พบฟาร์มตามตัวกรอง</div>';const t=cpTarget028(),unit=Cost028.groups[CP028.group].unit;return controls+cpPanel028('farm-summary',cpEsc028(f.name)+' · '+cpEsc028(f.region),`<div class="cp-stats">${cpStat028('ค่ายา-วัคซีน',f.values.medvac,t?.medvac,unit)}${cpStat028('ตาย-คัดทิ้ง',f.values.deadcull,t?.deadcull,unit)}<div class="cp-stat">ปริมาณที่ใช้คำนวณ<b>${cpN028(f.values.den,0)}</b>${CP028.group==='weaned'?'ตัว':'กก.'}</div></div>`)+`<div class="cp-grid">${cpPanel028('farm-trend',cpTrendTitle031('แนวโน้มค่ายา-วัคซีน',CP028.group,'medvac','farm-trend',f.id),cpTrend028(CP028.group,'medvac','farm-trend',f.id),cpChartTools028('farm-trend'))}${cpPanel028('farm-dead',cpTrendTitle031('แนวโน้มตาย-คัดทิ้ง',CP028.group,'deadcull','farm-dead',f.id),cpTrend028(CP028.group,'deadcull','farm-dead',f.id),cpChartTools028('farm-dead'))}</div>`+cpPanel028('composition','องค์ประกอบต้นทุนยา/วัคซีน',cpComposition028(f.rows),`<select data-cp="composition">${cpOptions028([['value','ตัวเลขต้นทุนต่อหน่วย'],['percent','ตัวเลขสัดส่วน (%)']],CP028.composition)}</select>`)+cpPanel028('farm-months','รายละเอียดรายเดือน',cpFarmMonths031(f,unit),'',true);}

function cpReview028(r){return `<div class="cp-stats">${Object.entries(r.counts).map(([g,n])=>`<div class="cp-stat">${Cost028.groups[g].label}<b>${n} ฟาร์ม</b></div>`).join('')}</div><p>ข้อมูลใหม่ ${r.rows} รายการ · แทนข้อมูลเดิมในช่วงเดียวกัน ${r.replaced} รายการ · เก็บข้อมูลนอกช่วงไฟล์ใหม่ไว้ตามเดิม</p>${r.scan?`<div class="cp-tablewrap"><table><tbody>${[['แถวต้นฉบับทั้งหมด',r.scan.total],['ไม่ใช่ INT (เก็บในไฟล์ต้นฉบับ)',r.scan.otherType],['ผลิตภัณฑ์นอกขอบเขต (เก็บในไฟล์ต้นฉบับ)',r.scan.otherProduct],['INT ที่เก็บสำหรับคำนวณ/รอตรวจ',r.scan.selected],['รอตรวจคู่ฟาร์ม',r.scan.pendingRows],['ปิดการแสดง',r.scan.disabledRows],['นอกเงื่อนไข GDU ของกลุ่มผลิต',r.scan.groupExcluded],['นำมาคำนวณ',r.scan.usedRows]].map(([l,n])=>`<tr><td>${l}</td><td>${Number(n).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:''}${r.errors.length?'<div class="cp-error">'+r.errors.map(cpEsc028).join('<br>')+'</div>':''}<div class="cp-warn">${r.warnings.map(cpEsc028).join('<br>')}</div><p class="cp-muted">ข้อมูลชุดเดิมยังใช้ได้จนกว่าการยืนยันชุดใหม่สำเร็จ</p><p><label><input type="checkbox" id="cpPublishAck">ตรวจข้อสังเกตและยืนยันการแทนที่ข้อมูลแล้ว</label></p><button class="primary" id="cpPublish" ${CP028.busy||r.errors.length?'disabled':''}>ยืนยันนำเข้าข้อมูล</button>`;}
function cpMapLabel028(id){const f=CP028.data.farms.find(f=>f.id===id);return f?f.name+' | '+f.region+' | '+f.id:'';}
function cpNorm028(x){return String(x).normalize('NFC').replace(/^ฟาร์ม\s*|^ฟ\.\s*/,'').replace(/\s+/g,'').toLowerCase();}
function cpReadWorker028(file,kind){return new Promise((resolve,reject)=>{const worker=new Worker('./cost-worker.js?v=39'),timer=setTimeout(()=>{worker.terminate();reject(Error('อ่านไฟล์นานเกินกำหนด'));},120000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();e.data.ok?resolve(e.data.data):reject(Error(e.data.error));};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(Error('โหลดตัวอ่าน Excel ไม่สำเร็จ กรุณาอัปโหลดไฟล์ frontend ให้ครบ'));};file.arrayBuffer().then(buffer=>worker.postMessage({buffer,name:file.name,kind},[buffer])).catch(reject);});}

function cpBase64028(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('อ่านไฟล์ไม่สำเร็จ'));reader.readAsDataURL(file);});}
async function cpUpload028(){const seq=CP028.seq,uid=state.user?.id,guard=()=>{if(seq!==CP028.seq||uid!==state.user?.id)throw Error('หยุดงานเนื่องจากเปลี่ยนผู้ใช้');};const s=CP028.stage;if(!s||CP028.busy)return;if(!$('#cpMappingAck')?.checked)return toast('กรุณายืนยันคู่ฟาร์ม');for(const el of document.querySelectorAll('[data-cp-map]')){const f=CP028.data.farms.find(f=>cpMapLabel028(f.id)===el.value);if(!f)return toast('ยังไม่จับคู่รหัส '+el.dataset.cpMap);s.mapping[el.dataset.cpMap]=f.id;}CP028.busy=true;$('#cpUpload').disabled=true;const progress=msg=>{const el=$('#cpProgress');if(el)el.textContent=msg;};try{const rows=s.pivot.source,parts=Math.ceil(rows.length/80);if(!s.uploadId){s.uploadId=crypto.randomUUID();const digest=await crypto.subtle.digest('SHA-256',await s.file.arrayBuffer());s.hash=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');s.base=CP028.data.id;}
 guard();progress('กำลังเก็บไฟล์ต้นฉบับ…');const b=await api('costDashboard028',{op:'begin',id:s.uploadId,base:s.base,name:s.name,hash:s.hash,base64:await cpBase64028(s.file),viewRevision:CP028.data.viewRevision,scan:s.pivot.scan,orgs:s.orgs,parts,rowCount:rows.length,periods:s.pivot.periods});guard();if(b.status==='STAGING'){for(let part=s.sent;part<parts;part++){progress('กำลังส่งข้อมูล '+(part+1)+' / '+parts+' ชุด');await api('costDashboard028',{op:'chunk',id:s.uploadId,part,data:rows.slice(part*80,(part+1)*80)});guard();s.sent=part+1;}}progress('กำลังตรวจยอดและเตรียมชุดข้อมูล…');const review=await api('costDashboard028',{op:'prepare',id:s.uploadId});guard();s.review=review;CP028.error='';}catch(e){if(seq===CP028.seq)CP028.error=e.message+' · สามารถกดส่งต่อได้โดยไม่เพิ่มข้อมูลชุดเดิมซ้ำ';}finally{if(seq===CP028.seq&&uid===state.user?.id){CP028.busy=false;cpRender028();}}}
async function cpPublish028(){const seq=CP028.seq,uid=state.user?.id;if(CP028.busy||!$('#cpPublishAck')?.checked)return toast('กรุณายืนยันผลตรวจ');CP028.busy=true;$('#cpPublish').disabled=true;try{await api('costDashboard028',{op:'publish',id:CP028.stage.uploadId,ack:true});if(seq!==CP028.seq||uid!==state.user?.id)return;CP028.stage=null;CP028.data=null;toast('นำเข้าข้อมูลต้นทุนสำเร็จ');}catch(e){if(seq===CP028.seq)CP028.error=e.message;}finally{if(seq===CP028.seq&&uid===state.user?.id){CP028.busy=false;CP028.data?cpRender028():cpLoad028();}}}
