function cpRegionOverview028(groups){if(groups.length===1&&groups[0]==='gdu'){const list=cpRows028('gdu');return cpPanel028('regions','เปรียบเทียบต้นทุนรายภาค · GDU',`<div class="cp-tablewrap"><table class="cp-region031"><thead><tr><th>ภาค</th><th>ฟาร์ม</th><th>ตาย-คัดทิ้ง (บาท/กก.)</th><th>ยา-วัคซีน (บาท/กก.)</th></tr></thead><tbody>${CP_REGIONS028.map(region=>{const farms=list.filter(f=>f.region===region).sort((a,b)=>a.name.localeCompare(b.name,'th'));return farms.map((f,i)=>`<tr>${i===0?`<th rowspan="${farms.length}">${cpEsc028(region)}</th>`:''}<td>${cpEsc028(f.name)}</td>${['deadcull','medvac'].map(m=>cpMetricCell031(f.values[m],cpTarget028('gdu')?.[m])).join('')}</tr>`).join('');}).join('')}</tbody></table></div>`,'',true);}return cpPanel028('regions','เปรียบเทียบต้นทุนรายภาค',`<div class="cp-tablewrap"><table class="cp-region031"><thead><tr><th rowspan="2">ภาค</th><th colspan="2" class="cp-weaned031">สุกรหย่านม <small>(บาท/ตัว)</small></th><th colspan="2" class="cp-fatten031">สุกรขุน <small>(บาท/กก.)</small></th></tr><tr><th>ตาย-คัดทิ้ง</th><th>ยา-วัคซีน</th><th>ตาย-คัดทิ้ง</th><th>ยา-วัคซีน</th></tr></thead><tbody>${CP_REGIONS028.map(region=>{const all=groups.map(g=>({g,rows:cpBase028(g).filter(r=>cpFarm028(r.farmId).region===region)}));if(!all.some(x=>x.rows.length))return '';return `<tr><th>${cpEsc028(region.replace(/^ภาค/,''))}</th>${all.map(({g,rows})=>{const v=Cost028.rates(rows),t=cpTarget028(g);return ['deadcull','medvac'].map(m=>cpMetricCell031(v[m],t?.[m])).join('');}).join('')}</tr>`;}).join('')}</tbody></table></div>`,'',true);}



