function cpBind030(){if($('#cpRegistryFind'))$('#cpRegistryFind').onclick=()=>{CP028.registrySearch=$('#cpRegistrySearch').value;cpRender028();};if($('#cpKPILoad'))$('#cpKPILoad').onclick=()=>{const year=Number($('#cpKPIYear').value);if(!Number.isInteger(year)||year<2000||year>2100)return toast('ปีไม่ถูกต้อง');CP028.kpiEditYear=year;cpRender028();};if($('#cpKPISave'))$('#cpKPISave').onclick=async()=>{if(CP028.busy)return;const year=CP028.kpiEditYear||CP028.year||2026,targets={weaned:{},fatten:{}},reason=$('#cpKPIReason').value.trim();document.querySelectorAll('[data-kpi-g]').forEach(e=>targets[e.dataset.kpiG][e.dataset.kpiM]=Number(e.value));if(!reason||Object.values(targets).some(g=>Object.values(g).some(v=>!Number.isFinite(v)||v<=0)))return toast('กรอก KPI มากกว่าศูนย์ครบ 4 ค่า และระบุเหตุผล');CP028.busy=true;$('#cpKPISave').disabled=true;const seq=CP028.seq;try{await api('costDashboard028',{op:'kpiSave',year,targets,reason,revision:CP028.data.kpis[year]?.revision||''});if(seq!==CP028.seq)return;toast('บันทึก KPI แล้ว');await cpReloadAfter030();}catch(e){if(seq===CP028.seq){CP028.busy=false;toast(e.message);cpRender028();}}};document.querySelectorAll('[data-reg-save]').forEach(b=>b.onclick=async()=>{if(CP028.busy)return;const row=b.closest('tr'),label=row.querySelector('[data-reg-farm]').value.trim(),farm=CP028.data.farms.find(f=>cpMapLabel028(f.id)===label),enabled=row.querySelector('[data-reg-enabled]').checked;if(label&&!farm)return toast('เลือกฟาร์มจากรายชื่อให้ถูกต้อง');if(enabled&&!farm)return toast('เลือกฟาร์มก่อนเปิดแสดง');const reason=prompt('เหตุผลที่ยืนยัน/แก้ไขคู่ฟาร์ม หรือเปิด–ปิดต้นทุน');if(!reason?.trim())return;const seq=CP028.seq;CP028.busy=true;b.disabled=true;try{await api('costDashboard028',{op:'registrySave',code:b.dataset.regSave,farmId:farm?.id||'',enabled,reason,revision:CP028.data.display.revision});if(seq!==CP028.seq)return;toast('บันทึกคู่และการแสดงต้นทุนแล้ว');await cpReloadAfter030();}catch(e){if(seq===CP028.seq){CP028.busy=false;toast(e.message);cpRender028();}}});}
function cpImportHTML028(){const s=CP028.stage;return `<section class="panel"><h2>นำเข้าต้นทุนรายเดือน</h2><p>อัปโหลดไฟล์ Pivot เท่านั้น ระบบใช้ KPI ที่ตั้งไว้แล้ว และจับคู่ด้วยรหัสบัญชี</p><div class="cp-tools"><label>ไฟล์ต้นทุน .xlsb / .xlsx<input id="cpPivotFile" type="file" accept=".xlsb,.xlsx" ${CP028.busy?'disabled':''}></label><button id="cpReadFiles" class="primary" ${CP028.busy?'disabled':''}>อ่านไฟล์และตรวจข้อมูล</button></div>${CP028.error?'<p class="cp-error">'+cpEsc028(CP028.error)+'</p>':''}<div id="cpProgress" role="status"></div>${s?`<h3>${cpEsc028(s.name)}</h3><p>ข้อมูลถึง ${CP_MONTHS028[s.pivot.period.month-1]} ${s.pivot.period.year+543} · ${s.orgs.length} รหัสบัญชี · ใช้ ${cpEsc028(s.kpi.name)}</p>${!s.review?`<div class="cp-stats"><div class="cp-stat">แถวทั้งหมด<b>${s.pivot.scan.total.toLocaleString()}</b></div><div class="cp-stat">INT ในผลิตภัณฑ์ที่รองรับ<b>${s.pivot.scan.selected.toLocaleString()}</b></div><div class="cp-stat">รหัสรอตรวจ<b>${s.orgs.filter(o=>!CP028.data.mapping[o.org]).length}</b></div></div><p>รหัสที่ยังไม่จับคู่จะเก็บรอตรวจ ไม่รวมในยอด ส่วนข้อมูลต้นฉบับทุกแถวเก็บในไฟล์สำรอง</p><p><label><input type="checkbox" id="cpMappingAck" ${s.uploadId?'checked disabled':''}>ยืนยันนำเข้าตามคู่รหัสล่าสุด และเก็บรหัสที่ยังไม่จับคู่ไว้รอตรวจ</label></p><button class="primary" id="cpUpload" ${CP028.busy?'disabled':''}>${s.uploadId?'ส่งต่อ / ตรวจสรุปอีกครั้ง':'บันทึกไฟล์และตรวจสรุป'}</button>`:cpReview028(s.review)}`:''}</section><section class="panel"><h2>ประวัติการนำเข้า</h2><div class="cp-tablewrap"><table><thead><tr><th>ไฟล์</th><th>เวลา</th><th>สถานะ</th><th></th></tr></thead><tbody>${(CP028.data.imports||[]).map(i=>`<tr><td>${cpEsc028(i.name)}</td><td>${cpEsc028(i.at)}</td><td>${i.active?'กำลังใช้งาน':({ARCHIVED:'นำออกจากชุดใช้งานแล้ว',PUBLISHED:'เก็บย้อนหลัง',PREPARED:'รอยืนยัน',STAGING:'ยังส่งไม่ครบ'})[i.status]||cpEsc028(i.status)}</td><td>${i.version===30&&i.status==='PUBLISHED'&&!i.active?`<button data-cp-rollback="${cpEsc028(i.id)}">กลับไปใช้ชุดนี้</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function cpReadFiles028(){const seq=CP028.seq,uid=state.user?.id,file=$('#cpPivotFile').files[0];if(!file)return toast('เลือกไฟล์ต้นทุน');if(file.size>16*1024*1024)return toast('ไฟล์ต้องไม่เกิน 16 MB');CP028.busy=true;$('#cpReadFiles').disabled=true;$('#cpProgress').textContent='กำลังอ่านไฟล์…';try{const pivot=await cpReadWorker028(file,'pivot'),kpi=CP028.data.kpis[pivot.period.year];if(seq!==CP028.seq||uid!==state.user?.id)return;if(!kpi)throw Error('กรุณาตั้ง KPI ปี '+pivot.period.year+' ในแท็บตั้งค่า KPI ก่อน');CP028.stage={name:file.name,file,pivot,kpi,orgs:pivot.orgs,mapping:CP028.data.mapping,uploadId:'',sent:0,review:null};CP028.error='';}catch(e){if(seq===CP028.seq)CP028.error=e.message;}finally{if(seq===CP028.seq){CP028.busy=false;cpRender028();}}}

const CP_COLOR_NAMES031={red:'แดง',orange:'ส้ม',yellow:'เหลือง',green:'เขียว'};
function cpDefaults031(){CP028.colors=['red'];CP028.streak='3';}
function cpTone031(value,target){return value===null||!Number.isFinite(value)||value<0||!(target>0)?'':value<=target?'cp-good':'cp-bad';}
function cpMetricCell031(v,t){return `<td class="num cp-bold031 ${cpTone031(v,t)}">${v===null?'':cpN028(v)}</td>`;}
function cpTrendTitle031(title,group,metric,key,farmId){const cfg=cpChartState028(key),from=CP028.from;let rows;try{if(cfg.mode==='cum')CP028.from=1;rows=cpBase028(group);}finally{CP028.from=from;}if(farmId)rows=rows.filter(r=>r.farmId===farmId);const months=[...new Set(rows.filter(r=>r.month>=from).map(r=>r.month))].sort((a,b)=>b-a);let value=null,month;for(const m of months){const v=Cost028.rates(rows.filter(r=>cfg.mode==='cum'?r.month<=m:r.month===m))[metric];if(v!==null){value=v;month=m;break;}}return `<span class="${cpTone031(value,cpTarget028(group)?.[metric])}" title="${month?'เทียบเป้าจากค่าล่าสุดที่แสดง: '+CP_MONTHS028[month-1]+' '+(CP028.year+543)+' · '+(cfg.mode==='cum'?'สะสม':'รายเดือน'):'ไม่มีค่าที่ประเมินได้'}">${cpEsc028(title)}</span>`;}
function cpRankPair031(list,start=0,count=Infinity){return `<div class="cp-rank-pair031">${['deadcull','medvac'].map(metric=>{const ordered=list.slice().sort((a,b)=>{const x=a.values[metric],y=b.values[metric];return x===null||y===null?x===y?a.name.localeCompare(b.name,'th'):x===null?1:-1:y-x||a.name.localeCompare(b.name,'th');}).slice(start,start+count),value=Cost028.rates(list.flatMap(f=>f.rows))[metric];return `<div><h3 class="${cpTone031(value,cpTarget028()?.[metric])}">${metric==='deadcull'?'ต้นทุนตาย-คัดทิ้ง':'ต้นทุนยา-วัคซีน'} <small>(${Cost028.groups[CP028.group].unit})</small></h3>${cpRanking028(ordered,metric)}</div>`;}).join('')}</div>`;}
function cpLatest031(){const ms=CP028.data.rows.filter(r=>r.year===CP028.year&&r.group===CP028.group).map(r=>r.month);return ms.length?{year:CP028.year,month:Math.max(...ms)}:null;}
function cpMonthRows031(id,year,month){const rows=CP028.data.rows.filter(r=>r.farmId===id&&r.group===CP028.group&&r.year===year&&(!CP028.bus.length||CP028.bus.includes(r.bu)));return rows.some(r=>r.month===month)?rows.filter(r=>cpIsCumulative035()?r.month<=month:r.month===month):[];}
function cpIsCumulative035(){return CP028.view==='compare'&&CP028.compareBasis035==='cum';}
function cpBasisLabel035(){return cpIsCumulative035()?'สะสม ม.ค. ถึงแต่ละเดือน':'รายเดือน';}
function cpRedRun031(id,n,end=cpLatest031()){if(!end)return false;for(let i=0;i<n;i++){const serial=end.year*12+end.month-1-i,year=Math.floor(serial/12),month=serial%12+1,rows=cpMonthRows031(id,year,month),target=CP028.data.kpis[CP028.targetYear||year]?.targets?.[CP028.group];if(!rows.length||Cost028.category(Cost028.rates(rows),target)!=='red')return false;}return true;}
function cpHeatTools031(){const years=[...new Set([CP028.year,...CP028.data.rows.map(r=>r.year)])].sort((a,b)=>b-a);return `<label>ปี<select data-cp="year">${cpOptions028(years.map(y=>[y,y+543]),CP028.year)}</select></label>${cpMulti028('regions','ภาค',CP_REGIONS028.map(x=>[x,x]))}<label>ฟาร์มที่แสดง<select data-cp="streak">${cpOptions028([['3','แดง 3 เดือน'],['2','แดง 2 เดือน'],['all','ทุกฟาร์ม']],CP028.streak)}</select></label>`;}
function cpHeadCount031(rows){if(!rows.length||rows.some(r=>r.head===null||r.head===undefined))return null;return rows.reduce((n,r)=>n+r.head,0);}
function cpFarmMonths031(f,unit){return `<div class="cp-tablewrap"><table class="cp-months031"><thead><tr><th>เดือน</th><th title="จำนวนหมูดี (ตัว) ตามไฟล์ต้นทุน">จำนวนสุกร (ตัว)</th><th>ยา-วัคซีน (บาท)</th><th>ยา-วัคซีน (${unit})</th><th>ตาย-คัดทิ้งสุทธิ (บาท)</th><th>ตาย-คัดทิ้ง (${unit})</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>i+1).filter(m=>m>=CP028.from&&m<=CP028.to).map(m=>{const r=cpMonthRows031(f.id,CP028.year,m),sum=Cost028.sum(r),v=Cost028.rates(r),head=cpHeadCount031(r),previous=cpHeadCount031(cpMonthRows031(f.id,m===1?CP028.year-1:CP028.year,m===1?12:m-1)),drop=head!==null&&previous>0&&head<previous*.9;return `<tr><th>${CP_MONTHS028[m-1]}</th><td class="num ${drop?'cp-bad cp-bold031':''}" ${drop?'title="ลดลง '+cpN028((previous-head)/previous*100,1)+'% จากเดือนก่อนหน้า"':''}>${head===null?'':cpN028(head,0)}</td>${[sum?.medvac,v.medvac,sum?.deadcull,v.deadcull].map(x=>'<td class="num">'+(x==null?'':cpN028(x))+'</td>').join('')}</tr>`;}).join('')}</tbody></table></div>`;}
